require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/session.php';require_once __DIR__.'/../../includes/functions.php';require_once __DIR__.'/../../includes/admin_layout.php';if(!is_admin_logged_in())redirect('../../index.php');if(($_SESSION['admin_role']??'admin')!=='admin'){http_response_code(403);exit('Administrator access required.');}
$eventId=(int)($_GET['event_id']??$_POST['event_id']??0);$error='';$issued=$_SESSION['issued_attendee']??null;unset($_SESSION['issued_attendee']);
$events=pg_query($conn,"SELECT id,title,status,start_at FROM events WHERE status<>'cancelled' ORDER BY start_at DESC");
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!verify_csrf_token($_POST['csrf_token']??''))$error='Security token expired.';else{$action=$_POST['action']??'';$id=(int)($_POST['id']??0);
  if($action==='create'){$name=trim($_POST['full_name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$org=trim($_POST['organization']??'');$code=strtoupper(trim($_POST['attendee_code']??''))?:generate_public_code('ATT',3);$password=trim($_POST['password']??'');if($password==='')$password=substr(strtoupper(bin2hex(random_bytes(6))),0,10);
   if($name==='')$error='Full name is required.';elseif($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))$error='Enter a valid email address.';elseif(!preg_match('/^[A-Z0-9_-]{4,40}$/',$code))$error='Attendee code must use 4–40 letters, numbers, dashes, or underscores.';elseif(strlen($password)<8)$error='Password must be at least 8 characters.';else{$r=pg_query_params($conn,'INSERT INTO attendees(attendee_code,full_name,email,phone,organization,password_hash) VALUES($1,$2,$3,$4,$5,$6) RETURNING id',[$code,$name,$email?:null,$phone?:null,$org,password_hash($password,PASSWORD_DEFAULT)]);if($r){$newId=(int)pg_fetch_result($r,0,0);$_SESSION['issued_attendee']=['name'=>$name,'code'=>$code,'password'=>$password];audit_log($conn,'attendee_created','attendee',$newId,['code'=>$code]);redirect('index.php'.($eventId?'?event_id='.$eventId:''));}else $error='That attendee code is already in use.';}
  }elseif($action==='register'&&$id&&$eventId){$ev=pg_query_params($conn,"SELECT capacity,(SELECT COUNT(*) FROM event_registrations WHERE event_id=events.id AND status='registered') registered FROM events WHERE id=$1 AND status NOT IN ('completed','cancelled')",[$eventId]);if(!$ev||!pg_num_rows($ev))$error='This event is not accepting registrations.';else{$e=pg_fetch_assoc($ev);$status=$e['capacity']!==null&&(int)$e['registered']>=(int)$e['capacity']?'waitlisted':'registered';$ticket=generate_public_code('TKT',5);$ok=pg_query_params($conn,'INSERT INTO event_registrations(event_id,attendee_id,ticket_code,status) VALUES($1,$2,$3,$4) ON CONFLICT(event_id,attendee_id) DO UPDATE SET status=EXCLUDED.status',[$eventId,$id,$ticket,$status]);if($ok){audit_log($conn,'event_registration_saved','event',$eventId,['attendee_id'=>$id,'status'=>$status]);redirect('index.php?event_id='.$eventId.'&message='.$status);}else $error='Registration could not be saved.';}}
  elseif($action==='cancel'&&$id&&$eventId){pg_query_params($conn,"UPDATE event_registrations SET status='cancelled' WHERE event_id=$1 AND attendee_id=$2 AND NOT EXISTS(SELECT 1 FROM attendance_records WHERE registration_id=event_registrations.id)",[$eventId,$id]);redirect('index.php?event_id='.$eventId.'&message=cancelled');}
  elseif($action==='toggle'&&$id){pg_query_params($conn,"UPDATE attendees SET status=CASE WHEN status='active' THEN 'disabled' ELSE 'active' END,account_status=CASE WHEN status='active' THEN 'disabled' ELSE 'active' END,updated_at=NOW() WHERE id=$1",[$id]);audit_log($conn,'student_account_toggled','attendee',$id);redirect('index.php'.($eventId?'?event_id='.$eventId:''));}
 }
}
$search=trim($_GET['q']??'');$params=[];$where='';if($search!==''){$params=['%'.$search.'%'];$where='WHERE a.full_name ILIKE $1 OR a.attendee_code ILIKE $1 OR a.email ILIKE $1 OR d.code ILIKE $1 OR d.name ILIKE $1 OR c.code ILIKE $1 OR c.name ILIKE $1 OR a.year_level ILIKE $1 OR a.section ILIKE $1';}
$sql="SELECT a.*,d.code department_code,d.name department_name,c.code course_code,c.name course_name,r.id registration_id,r.status registration_status,r.ticket_code,ar.check_in_at FROM attendees a LEFT JOIN departments d ON d.id=a.department_id LEFT JOIN courses c ON c.id=a.course_id LEFT JOIN event_registrations r ON r.attendee_id=a.id AND r.event_id=".($eventId?'$'.(count($params)+1):'NULL')." LEFT JOIN attendance_records ar ON ar.registration_id=r.id $where ORDER BY a.created_at DESC";if($eventId)$params[]=$eventId;$rows=$params?pg_query_params($conn,$sql,$params):pg_query($conn,$sql);
$selected=null;if($eventId){$r=pg_query_params($conn,'SELECT * FROM events WHERE id=$1',[$eventId]);$selected=$r&&pg_num_rows($r)?pg_fetch_assoc($r):null;}
$stats=pg_query($conn,"SELECT COUNT(*) total,COUNT(*) FILTER(WHERE account_status='active') active,COUNT(*) FILTER(WHERE account_status='disabled') disabled,COUNT(*) FILTER(WHERE must_complete_profile) temporary FROM attendees");$sum=$stats?pg_fetch_assoc($stats):['total'=>0,'active'=>0,'disabled'=>0,'temporary'=>0];admin_page_start('Attendees','attendees');?>
