 type="hidden" name="id" value="<?=(int)$a['id']?>"><input type="hidden" name="action" value="toggle"><button class="btn small secondary"><?=$a['account_status']==='active'?'Disable':'Enable'?></button></form><a class="btn small danger" href="../data/index.php?focus=student&amp;id=<?=(int)$a['id']?>#record-student-<?=(int)$a['id']?>"><i class="fas fa-file-export"></i> Export / Delete</a></div></td></tr><?php endwhile;endif;if(!$rows||pg_num_rows($rows)===0):?><tr><td colspan="6" class="empty">No students found.</td></tr><?php endif;?></tbody></table></div></div>
<?php if($issued):?><script>
document.addEventListener('DOMContentLoaded',()=>{const source=document.getElementById('issuedCredentials');if(!source)return;const credentials={name:source.dataset.name,code:source.dataset.code,password:source.dataset.password};const escapeHtml=value=>String(value).replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));const copyText=async value=>{if(navigator.clipboard&&window.isSecureContext)return navigator.clipboard.writeText(value);const area=document.createElement('textarea');area.value=value;area.style.position='fixed';area.style.opacity='0';document.body.appendChild(area);area.select();document.execCommand('copy');area.remove()};const showCopied=button=>{const original=button.innerHTML;button.innerHTML='<i class="fas fa-check"></i> Copied';button.classList.add('copied');setTimeout(()=>{button.innerHTML=original;button.classList.remove('copied')},1400)};Swal.fire({...amsSwalOptions(),customClass:{popup:'credential-popup',htmlContainer:'credential-modal-body',confirmButton:'credential-confirm'},title:'Account created successfully',icon:'success',html:`<div class="credential-student"><span>Login credentials for</span><strong>${escapeHtml(credentials.name)}</strong></div><div class="credential-warning"><i class="fas fa-triangle-exclamation"></i><div><strong>Save these credentials now</strong><small>The initial password is displayed only once and cannot be retrieved later.</small></div></div><div class="credential-field"><label>Login code</label><div><code>${escapeHtml(credentials.code)}</code><button type="button" data-copy="code"><i class="fas fa-copy"></i> Copy</button></div></div><div class="credential-field"><label>Initial password</label><div><code id="credentialPassword" data-visible="false">${'•'.repeat(Math.max(8,credentials.password.length))}</code><button type="button" data-toggle-password><i class="fas fa-eye"></i> Show</button><button type="button" data-copy="password"><i class="fas fa-copy"></i> Copy</button></div></div><button type="button" class="credential-copy-all" data-copy="all"><i class="fas fa-copy"></i> Copy all credentials</button><p class="credential-hint"><i class="fas fa-shield-halved"></i> Send these privately to the student. Do not post them in a group chat.</p>`,confirmButtonText:'I have saved the credentials',allowOutsideClick:false,allowEscapeKey:false,didOpen:popup=>{popup.querySelectorAll('[data-copy]').forEach(button=>button.addEventListener('click',async()=>{const type=button.dataset.copy;const value=type==='code'?credentials.code:type==='password'?credentials.password:`Student: ${credentials.name}\nLogin code: ${credentials.code}\nInitial password: ${credentials.password}`;try{await copyText(value);showCopied(button)}catch(error){Swal.showValidationMessage('Copy failed. Please select and copy the credentials manually.')}}));popup.querySelector('[data-toggle-password]').addEventListener('click',event=>{const button=event.currentTarget,passwordNode=popup.querySelector('#credentialPassword'),visible=passwordNode.dataset.visible==='true';passwordNode.textContent=visible?'•'.repeat(Math.max(8,credentials.password.length)):credentials.password;passwordNode.dataset.visible=visible?'false':'true';button.innerHTML=visible?'<i class="fas fa-eye"></i> Show':'<i class="fas fa-eye-slash"></i> Hide'})}}).then(()=>source.remove())});
</script><?php endif;?>
